// Generates packages/shared/src/db-types.ts from the local Supabase database.
// Written from Node (not a shell redirect) so the file is always UTF-8 with LF line endings.
import { spawnSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const result = spawnSync("pnpm exec supabase gen types typescript --local", {
  encoding: "utf8",
  shell: true,
});

if (result.status !== 0) {
  console.error(result.stderr || "supabase gen types failed (is `pnpm db:start` running?)");
  process.exit(result.status ?? 1);
}

const header = `/**
 * Generated by \`pnpm db:types\` from the local database. Do not edit by hand.
 */
`;
writeFileSync(
  new URL("../packages/shared/src/db-types.ts", import.meta.url),
  header + result.stdout.replace(/\r\n/g, "\n"),
);
console.log("packages/shared/src/db-types.ts updated");
